    const paragraphs = b ? b.split('\n\n').length : 0;
    if (paragraphs < t.paragraphsMin || paragraphs > t.paragraphsMax) issues.push('block ' + (i + 1) + ' has ' + paragraphs + ' paragraphs; required 2-8');
